    Books are numbered 1-5. A set of n distinct books gets a discount:
    1: 0%, 2: 5%, 3: 10%, 4: 20%, 5: 25% (base price 800 cents).
    """
    counts = [0, 0, 0, 0, 0]
    for b in basket:
        counts[b - 1] += 1

    set_price = {1: 800, 2: 760, 3: 720, 4: 640, 5: 600}

    def best(c):
        c = list(c)
        if sum(c) == 0:
            return 0
        best_val = sum(n * set_price[n] for n in c if n)  # naive: one set per book
        for i in range(5):
            for j in range(i + 1, 5):
                if c[i] and c[j]:
                    c2 = c[:]
                    c2[i] -= 1
                    c2[j] -= 1
                    val = set_price[2] + best(c2)
                    if val < best_val:
                        best_val = val
        return best_val

    return best(counts)

